//! `SubtitlesASS` (`additional/file/subtitle_ass.py`): the subtitle ASS
//! renderer, styled by the `subtitle_style` config group.

use serde_json::Value;

use crate::time::format_ass_time_by_seconds;

const ASS_BASE: &str = r#"[Script Info]
; Script generated by Bili23 Downloader
; http://bili23.scott-sloan.cn
Title: {title}
ScriptType: v4.00+
WrapStyle: 2
Collisions: Normal
ScaledBorderAndShadow: yes
Aspect Ratio: {width}:{height}
YCbCr Matrix: TV.601
PlayResX: {width}
PlayResY: {height}

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
{style}

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
{dialogues}
"#;

/// The `subtitle_style` config tree. Fields mirror the Python dict keys.
#[derive(Debug, Clone, PartialEq)]
pub struct SubtitleStyle {
    pub font_name: String,
    pub font_size: i64,
    pub font_bold: bool,
    pub font_italic: bool,
    pub font_underline: bool,
    pub font_strike: bool,
    pub border: f64,
    pub shadow: f64,
    pub primary_color: String,
    pub secondary_color: String,
    pub border_color: String,
    pub shadow_color: String,
    pub margin_left: i64,
    pub margin_right: i64,
    pub margin_vertical: i64,
    pub width: i64,
    pub height: i64,
    pub alignment: i64,
}

impl SubtitleStyle {
    /// Defaults from `crates/config/src/defaults.json` (`Additional.subtitle_style`).
    pub fn default_style() -> Self {
        Self {
            font_name: "黑体".to_owned(),
            font_size: 36,
            font_bold: false,
            font_italic: false,
            font_underline: false,
            font_strike: false,
            border: 1.0,
            shadow: 0.0,
            primary_color: "&H00FFFFFF".to_owned(),
            secondary_color: "&H000000FF".to_owned(),
            border_color: "H00000000".to_owned(),
            shadow_color: "H00000000".to_owned(),
            margin_left: 10,
            margin_right: 10,
            margin_vertical: 20,
            width: 1280,
            height: 720,
            alignment: 2,
        }
    }

    /// Parses the config `Value` (the `subtitle_style` group). Missing or
    /// mistyped pieces fall back to the defaults above, mirroring how the
    /// Python dict always carries every key.
    pub fn from_config(value: &Value) -> Self {
        let d = Self::default_style();
        let g = |group: &str| value.get(group).cloned().unwrap_or(Value::Null);
        let s = |group: &str, key: &str, default: String| {
            g(group)
                .get(key)
                .and_then(Value::as_str)
                .unwrap_or(&default)
                .to_owned()
        };
        let i = |group: &str, key: &str, default: i64| {
            g(group).get(key).and_then(Value::as_i64).unwrap_or(default)
        };
        let f = |group: &str, key: &str, default: f64| {
            g(group).get(key).and_then(Value::as_f64).unwrap_or(default)
        };
        let b = |key: &str, default: bool| {
            g("font")
                .get(key)
                .and_then(Value::as_bool)
                .unwrap_or(default)
        };
        Self {
            font_name: s("font", "name", d.font_name),
            font_size: i("font", "size", d.font_size),
            font_bold: b("bold", d.font_bold),
            font_italic: b("italic", d.font_italic),
            font_underline: b("underline", d.font_underline),
            font_strike: b("strike", d.font_strike),
            border: f("border", "border", d.border),
            shadow: f("border", "shadow", d.shadow),
            primary_color: s("color", "primary", d.primary_color),
            secondary_color: s("color", "secondary", d.secondary_color),
            border_color: s("color", "border", d.border_color),
            shadow_color: s("color", "shadow", d.shadow_color),
            margin_left: i("margin", "left", d.margin_left),
            margin_right: i("margin", "right", d.margin_right),
            margin_vertical: i("margin", "vertical", d.margin_vertical),
            width: i("resolution", "width", d.width),
            height: i("resolution", "height", d.height),
            alignment: value
                .get("Alignment")
                .and_then(Value::as_i64)
                .unwrap_or(d.alignment),
        }
    }
}

/// Renders the whole ASS document for `data` under `title`.
pub fn generate(data: &Value, title: &str, style: &SubtitleStyle) -> String {
    let style_str = format!(
        "Style: Default,{},{},{},{},{},{},{},{},{},{},100,100,0,0,1,{},{},{},{},{},{},1",
        style.font_name,
        style.font_size,
        style.primary_color,
        style.secondary_color,
        style.border_color,
        style.shadow_color,
        style.font_bold as i64,
        style.font_italic as i64,
        style.font_underline as i64,
        style.font_strike as i64,
        crate::py_float(style.border),
        crate::py_float(style.shadow),
        style.alignment,
        style.margin_left,
        style.margin_right,
        style.margin_vertical,
    );

    let mut dialogues = Vec::new();
    if let Some(body) = data.get("body").and_then(Value::as_array) {
        for item in body {
            let from = item.get("from").and_then(Value::as_f64).unwrap_or(0.0);
            let to = item.get("to").and_then(Value::as_f64).unwrap_or(0.0);
            let content = item.get("content").and_then(Value::as_str).unwrap_or("");
            dialogues.push(format!(
                "Dialogue: 0,{},{},Default,,0,0,0,,{content}",
                format_ass_time_by_seconds(from),
                format_ass_time_by_seconds(to),
            ));
        }
    }

    ASS_BASE
        .replace("{title}", title)
        .replace("{style}", &style_str)
        .replace("{dialogues}", &dialogues.join("\n"))
        .replace("{width}", &style.width.to_string())
        .replace("{height}", &style.height.to_string())
}
